39	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
40	import org.springframework.samples.petclinic.rest.validation.OwnerRequestValidator;
41	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.security.access.prepost.PreAuthorize;
44	import org.springframework.web.bind.annotation.CrossOrigin;
45	import org.springframework.web.bind.annotation.RequestMapping;
46	import org.springframework.web.bind.annotation.RestController;
47	import org.springframework.web.util.UriComponentsBuilder;
48	
49	import jakarta.transaction.Transactional;
50	
51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    private final OwnerRequestValidator ownerRequestValidator;
69	
70	    private final TelephoneNormalizer telephoneNormalizer;
71	
72	    private final EmailNormalizer emailNormalizer;
73	
74	    public OwnerRestControllerV1(ClinicService clinicService,
75	                                 OwnerMapper ownerMapper,
76	                                 PetMapper petMapper,
77	                                 VisitMapper visitMapper,
78	                                 OwnerRequestValidator ownerRequestValidator,
79	                                 TelephoneNormalizer telephoneNormalizer,
80	                                 EmailNormalizer emailNormalizer) {
81	        this.clinicService = clinicService;
82	        this.ownerMapper = ownerMapper;
83	        this.petMapper = petMapper;
84	        this.visitMapper = visitMapper;
85	        this.ownerRequestValidator = ownerRequestValidator;
86	        this.telephoneNormalizer = telephoneNormalizer;
87	        this.emailNormalizer = emailNormalizer;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        this.ownerRequestValidator.validate(ownerFieldsDto);
119	        String telephone = this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
120	        ownerFieldsDto.setTelephone(telephone);
121	        ownerFieldsDto.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
122	        if (!this.clinicService.findOwnerByTelephone(telephone).isEmpty()) {
123	            throw new DuplicateTelephoneException(telephone);
124	        }
125	        HttpHeaders headers = new HttpHeaders();
126	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
127	        this.clinicService.saveOwner(owner);
128	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
129	        headers.setLocation(UriComponentsBuilder.newInstance()
130	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
131	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
137	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
138	        if (currentOwner == null) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        currentOwner.setAddress(ownerFieldsDto.getAddress());
142	        currentOwner.setCity(ownerFieldsDto.getCity());
143	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
144	        currentOwner.setLastName(ownerFieldsDto.getLastName());
145	        currentOwner.setTelephone(this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
146	        currentOwner.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
147	        this.clinicService.saveOwner(currentOwner);
148	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Transactional
153	    @Override
154	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
155	        Owner owner = this.clinicService.findOwnerById(ownerId);
156	        if (owner == null) {
157	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
158	        }
159	        this.clinicService.deleteOwner(owner);
160	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Override
165	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
166	        Owner owner = this.clinicService.findOwnerById(ownerId);
167	        if (owner == null) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        HttpHeaders headers = new HttpHeaders();
171	        Pet pet = petMapper.toPet(petFieldsDto);
172	        owner.setId(ownerId);
173	        pet.setOwner(owner);
174	        pet.getType().setName(null);
175	        this.clinicService.savePet(pet);
176	        PetDto petDto = petMapper.toPetDto(pet);
177	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
178	            .buildAndExpand(pet.getId()).toUri());
179	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
180	    }
181	
182	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
183	    @Override
184	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
185	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
186	        if (currentOwner != null) {
187	            Pet currentPet = this.clinicService.findPetById(petId);
188	            if (currentPet != null) {
189	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
190	                currentPet.setName(petFieldsDto.getName());
191	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
192	                this.clinicService.savePet(currentPet);
193	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
194	            }
195	        }
196	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
197	    }
198	
199	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
200	    @Override
201	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
202	        HttpHeaders headers = new HttpHeaders();
203	        Visit visit = visitMapper.toVisit(visitFieldsDto);
204	        Pet pet = new Pet();
205	        pet.setId(petId);
206	        visit.setPet(pet);
207	        this.clinicService.saveVisit(visit);
208	        VisitDto visitDto = visitMapper.toVisitDto(visit);
209	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
210	            .buildAndExpand(visit.getId()).toUri());
211	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
212	    }
213	
214	
215	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
216	    @Override
217	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
218	        Owner owner = this.clinicService.findOwnerById(ownerId);
219	        if (owner != null) {
220	            Pet pet = owner.getPet(petId);
221	            if (pet != null) {
222	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
223	            }
224	        }
225	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
226	    }
227	}
